(()=>{'use strict';let queued=false;function fix(){queued=false;const root=document.querySelector('#main-content');if(!root||document.documentElement.dataset.patiView!=='home')return;const story=root.querySelector(':scope > .stories-section');if(!story)return;for(const child of Array.from(root.children)){if(child===story)break;if(child.matches('script,style,.pati-home-feed-tabs'))continue;const isEmpty=!child.textContent.trim()&&!child.querySelector('img,video,iframe,button,input,canvas,a');if(isEmpty){child.classList.add('buchee-blank-before-stories');child.style.setProperty('display','none','important')}}const first=story.getBoundingClientRect();const main=root.getBoundingClientRect();if(first.top-main.top>25){root.style.setProperty('padding-top','0','important');root.style.setProperty('margin-top','0','important');story.style.setProperty('margin-top','0','important')}}function schedule(){if(!queued){queued=true;requestAnimationFrame(fix)}}new MutationObserver(schedule).observe(document.querySelector('#main-content')||document.documentElement,{childList:true,subtree:false});document.addEventListener('DOMContentLoaded',schedule);schedule()})();